template:
% 参数由系统自动注入：\def\radius{3} \def\anglea{60} \def\showcircle{1} \def\showradius{1} \def\showchord{0} \def\showsector{0} \def\showsegment{0} \def\showangle{0} \def\showcenter{1} \def\showlabels{1} \def\showcoord{0} \def\cx{0} \def\cy{0}
% 视觉归一化：区分坐标模式与裸图模式
\ifnum\showcoord>0
  \pgfmathtruncatemacro{\xleft}{floor(\cx - \radius - 0.8)}
  \pgfmathtruncatemacro{\xright}{ceil(\cx + \radius + 0.8)}
  \pgfmathtruncatemacro{\ybottom}{floor(\cy - \radius - 0.8)}
  \pgfmathtruncatemacro{\ytop}{ceil(\cy + \radius + 0.8)}
  \pgfmathsetmacro{\xrange}{\xright - \xleft}
  \pgfmathsetmacro{\yrange}{\ytop - \ybottom}
  \pgfmathsetmacro{\figscale}{6.0 / max(\xrange, \yrange)}
\else
  \pgfmathsetmacro{\figscale}{3 / \radius}
\fi
% 装饰尺寸：scale= 会同时缩放坐标和 pt 单位长度，故绝对尺寸除以 figscale 抵消，保证视觉大小恒定。
\pgfmathsetmacro{\dotr}{1.6/\figscale}
\pgfmathsetmacro{\loff}{0.34/\figscale}
% A、B 关于正 x 轴对称，圆心角 anglea 平分在 x 轴两侧，图形居中稳定。
% anglea=0 时 A、B 重合，退化为「圆 + 单条半径 OA」；anglea=180 时弦 AB 即直径。
\pgfmathsetmacro{\hasb}{\anglea > 0 ? 1 : 0}
\pgfmathsetmacro{\halfa}{\anglea/2}
\pgfmathsetmacro{\Ax}{\cx + \radius*cos(\halfa)}
\pgfmathsetmacro{\Ay}{\cy - \radius*sin(\halfa)}
\pgfmathsetmacro{\Bx}{\cx + \radius*cos(\halfa)}
\pgfmathsetmacro{\By}{\cy + \radius*sin(\halfa)}
% A、B 只在被某个元素引用时才点出来；整圆之外什么都不画时应是一个干净的圆。
% 弦/扇形/弓形在 anglea=0 时本身不画，故乘 hasb，避免这些开关在退化情形下只点出一个点。
\pgfmathsetmacro{\ptshow}{max(\showradius, \hasb*max(\showchord,\showsector,\showsegment), 1 - \showcircle)}
% 字母沿径向朝外，再各自多推开 18 度，保证 anglea 很小时 A、B 的字母不挤在一起
\pgfmathsetmacro{\dirla}{\anglea > 0 ? -\halfa - 18 : 0}
\pgfmathsetmacro{\dirlb}{\halfa + 18}
\begin{tikzpicture}[scale=\figscale, every node/.style={font=\small, fill=none, inner sep=1.5pt}]
    % ===== 坐标系（showcoord=1 时绘制）=====
  \ifnum\showcoord>0
    \draw[->, thick] (\xleft-0.5, 0) -- (\xright+0.5, 0) node[right] {$x$};
    \draw[->, thick] (0, \ybottom-0.5) -- (0, \ytop+0.5) node[above] {$y$};
  \fi
  \coordinate (O) at (\cx,\cy);
  \coordinate (A) at (\Ax,\Ay);
  \coordinate (B) at (\Bx,\By);
  % 填充先画，避免盖住后面的线
  \ifdim\hasb pt>0pt
    \ifnum\showsector>0
      \fill[green!12] (O) -- (A) arc[start angle=-\halfa, end angle=\halfa, radius=\radius] -- cycle;
    \fi
    \ifnum\showsegment>0
      \fill[green!12] (A) arc[start angle=-\halfa, end angle=\halfa, radius=\radius] -- cycle;
    \fi
  \fi
  % 整圆轮廓；关闭时只画弧 AB，图形退化为扇形/弓形/弧单独成图
  \ifnum\showcircle>0
    \draw[thick] (O) circle [radius=\radius];
  \else
    \ifdim\hasb pt>0pt
      \draw[thick] (A) arc[start angle=-\halfa, end angle=\halfa, radius=\radius];
    \fi
  \fi
  % 半径：anglea=0 时 OA、OB 重合，只画一条
  \ifnum\showradius>0
    \draw[thick] (O) -- (A);
    \ifdim\hasb pt>0pt
      \draw[thick] (O) -- (B);
    \fi
  \fi
  % 弦 AB（anglea=180 时即直径）
  \ifdim\hasb pt>0pt
    \ifnum\showchord>0
      \draw[thick] (A) -- (B);
    \fi
  \fi
  % 圆心角 ∠AOB 的角弧（需两条半径存在才有夹角可标）
  \ifdim\hasb pt>0pt
    \ifnum\showangle>0
      \ifnum\showradius>0
        % 圆心角很小时固定半径的角弧会短到看不见，故按「弧长约 0.30cm」反推半径，上界不超过 0.55 倍圆半径
        \pgfmathsetmacro{\arcneed}{(0.30/\figscale)*57.2958/max(\anglea,0.5)}
        \pgfmathsetmacro{\arcr}{min(max(0.45/\figscale, \arcneed), \radius*0.55)}
        \draw[thick] ({\cx+\arcr*cos(\halfa)},{\cy+\arcr*sin(\halfa)}) arc[start angle=\halfa, end angle=-\halfa, radius=\arcr];
      \fi
    \fi
  \fi
  % 端点
  \ifdim\ptshow pt>0pt
    \fill (A) circle [radius=\dotr pt];
    \ifnum\showlabels>0
      \node at ({\Ax + \loff*cos(\dirla)},{\Ay + \loff*sin(\dirla)}) {$A$};
    \fi
    \ifdim\hasb pt>0pt
      \fill (B) circle [radius=\dotr pt];
      \ifnum\showlabels>0
        \node at ({\Bx + \loff*cos(\dirlb)},{\By + \loff*sin(\dirlb)}) {$B$};
      \fi
    \fi
  \fi
  % 圆心 O
  \ifnum\showcenter>0
    \fill (O) circle [radius=\dotr pt];
    \ifnum\showlabels>0
      \node[below left=3pt] at (O) {$O$};
    \fi
  \fi
\end{tikzpicture}
